$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$task='P:\JudasValidation\PreAlphaPass5';$name='JudasValidation-PreAlphaPass5-Gui'
[pscustomobject]@{utc=[DateTime]::UtcNow.ToString('o');task=(Get-ScheduledTask -TaskName $name|Select-Object State,TaskName);info=(Get-ScheduledTaskInfo -TaskName $name|Select-Object LastRunTime,LastTaskResult);rows=@(Get-ChildItem -LiteralPath "$task\GuiWork\Results" -Filter '*.json' -ErrorAction SilentlyContinue|ForEach-Object {Get-Content -Raw -LiteralPath $_.FullName|ConvertFrom-Json}|Select-Object label,exit,expected,passed,seconds);failure=if(Test-Path "$task\GuiWork\desktop-failure.log"){Get-Content -Raw "$task\GuiWork\desktop-failure.log"}else{$null};finished=Test-Path "$task\FUNCTIONAL_RESULTS.json"}|ConvertTo-Json -Depth 7
